def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    balance = 0
    current_group = ""
    for char in paren_string:
        if char == ' ':
            continue
        if char == '(':
            balance += 1
            current_group += '('
        if char == ')':
            balance -= 1
            current_group += ')'
        if balance == 0:
            result.append(current_group)
            current_group = ""
    return result

