def get_max_triples(n):
    # Count indices where a[i] ≡ 0 mod 3 (i ≡ 2 mod 3)
    count_0 = (n - 2) // 3 + 1 if n >= 2 else 0
    # Count indices where a[i] ≡ 1 mod 3 (i ≡ 0 or 1 mod 3)
    count_1 = n - count_0

    # Compute combinations C(k, 3) = k*(k-1)*(k-2)//6
