def sequence(n):
    if n == 1 or n == 2:
            return 1
    # Create a memoization dictionary
    memo = {1: 1, 2: 1}

    for i in range(3, n + 1):
            # sequence(i) = sequence(sequence(i-1)) + sequence(i-2)
            prev = memo[i-1]
            prev2 = memo[i-2]
            memo[i] = memo[prev] + memo[prev2]

    return memo[n]
